const items = $input.all();
const results = [];
const secret = $env.LENDLOOP_WEBHOOK_SECRET || "lendloop_shared_hmac_secret_2026";
const convexUrl = ($env.CONVEX_SITE_URL || "http://localhost:3000").replace(/\/+$/, "");
const todayStr = new Date().toISOString().split("T")[0];

for (const item of items) {
  const loan = item.json;
  if (!loan || !loan.loanId) continue;

  // Deterministic Idempotency Key: prevents duplicate reminders on retries
  const idempotencyKey = `overdue-${loan.loanId}-${todayStr}`;

  const writebackBody = {
    loanId: loan.loanId,
    idempotencyKey,
    status: "sent",
    details: `Automated overdue reminder sent to ${loan.borrowerEmail} for tool ${loan.toolName} (${loan.daysOverdue} days overdue)`
  };

  const bodyString = JSON.stringify(writebackBody);
  const writebackSignature = computeHmacSha256(secret, bodyString);

  results.push({
    json: {
      loanId: loan.loanId,
      toolName: loan.toolName,
      borrowerEmail: loan.borrowerEmail,
      borrowerName: loan.borrowerName,
      endDate: loan.endDate,
      daysOverdue: loan.daysOverdue,
      idempotencyKey,
      writebackUrl: `${convexUrl}/record-reminder`,
      writebackBody,
      writebackSignature
    }
  });
}

return results;

// Simulate / Dispatch Email Reminder to Borrower
const loan = $input.item.json;

